{"source":"import sys
import csv
import json
import re
import io
from decimal import Decimal, ROUND_HALF_UP, InvalidOperation

TWO = Decimal("0.01")


def normalize_category(raw):
    # Collapse runs of whitespace to a single space, then casefold.
    collapsed = re.sub(r"\s+", " ", raw).strip().casefold()
    return collapsed if collapsed else "uncategorized"


def main():
    if len(sys.argv) < 2:
        sys.stderr.write("usage: solution.py <input.csv>\n")
        return 2

    path = sys.argv[1]
    # Read raw bytes and decode as UTF-8 to preserve input bytes exactly.
    with open(path, "rb") as fh:
        data = fh.read().decode("utf-8")

    reader = csv.reader(io.StringIO(data))
    try:
        header = next(reader)
    except StopIteration:
        header = []

    # Map header names (stripped, casefolded) to column index.
    col = {}
    for idx, name in enumerate(header):
        col.setdefault(name.strip().casefold(), idx)

    ci = col.get("category")
    ai = col.get("amount")
    si = col.get("status")

    totals = {}  # normalized category -> Decimal sum of rounded amounts

    for row in reader:
        if si is not None and si < len(row):
            status = row[si].strip().casefold()
        else:
            status = ""
        if status != "paid":
            continue

        if ci is not None and ci < len(row):
            category = normalize_category(row[ci])
        else:
            category = "uncategorized"

        if ai is None or ai >= len(row):
            continue
        amount_raw = row[ai].strip()
        try:
            amount = Decimal(amount_raw)
        except (InvalidOperation, ValueError):
            continue

        rounded = amount.quantize(TWO, rounding=ROUND_HALF_UP)
        totals[category] = totals.get(category, Decimal("0")) + rounded

    categories = []
    grand = Decimal("0")
    for name in sorted(totals):
        total = totals[name].quantize(TWO, rounding=ROUND_HALF_UP)
        if total == 0:
            total = Decimal("0.00")
        grand += total
        categories.append({"category": name, "total": str(total)})

    grand = grand.quantize(TWO, rounding=ROUND_HALF_UP)
    if grand == 0:
        grand = Decimal("0.00")

    result = {"categories": categories, "total": str(grand)}
    sys.stdout.write(json.dumps(result, separators=(",", ":")))
    return 0


if __name__ == "__main__":
    sys.exit(main())"}

